//! The instruction set: opcodes, operands and metadata.
//!
//! Encoding and decoding are generated by `bytecodegen`.

use bytecodegen::bytecode_list;

use crate::runtime::interp::profile::{
    ArithProfile, ArrayProfile, CallLinkInfo, SlotSite, ValueProfile,
};

pub use super::operand::*;
pub use bytecodegen::{WIDE16_PREFIX, WIDE32_PREFIX};

bytecode_list! {
    section Bytecode {
        preserve_order = true;

        OpNop {}

        /// Check argc, frame room, and the hot counter.
        OpEnter { args { argc: Count, frame: Count } }
        /// Like `enter` for a procedure with a rest argument: move the extra
        /// arguments to `r[base..]` and their count to `r[cnt]`.
        OpEnterRest { args { required: Count, cnt: Register, base: Register, frame: Count } }

        /// Single-value entry. Pop `frame` slots, the value is written to
        /// `r[dst]`. `mask`: live registers of the caller. `mv`: 0 = error on
        /// any count but 1, 1 = ignore extra values.
        OpReturnPoint {
            args { frame: Count, mask: PoolReference, mv: Count, dst: Register }
            metadata { profile: ValueProfile }
        }
        /// Single-value entry of a return point that takes several values:
        /// continue at the next instruction (a `retpt_mv*`) with a count of 1.
        OpReturnPointForward { args { frame: Count, mask: PoolReference } }
        /// Multiple-value entry: exactly `nvals` values.
        OpReturnPointValues { args { nvals: Count, frame: Count } }
        /// Multiple-value entry: `nvals` or more, the extra count goes to `r[frame]`.
        OpReturnPointValuesRest { args { nvals: Count, frame: Count } }

        OpMove { args { dst: Register, src: Register } }
        OpLoadConstant { args { dst: Register, constant: Constant } }
        OpLoadImmediate { args { dst: Register, value: Immediate } }
        /// `dst` = the immediate whose raw bits are `bits`.
        OpLoadRaw { args { dst: Register, bits: Count } }
        OpCellRef {
            args { dst: Register, constant: Constant }
            metadata { profile: ValueProfile }
        }
        OpCellSet { args { constant: Constant, src: Register } }
        /// `dst` = a procedure the runtime provides (`RuntimeProc`).
        OpRuntimeProcedure { args { dst: Register, id: Count } }

        OpClosure { args { dst: Register, constant: Constant, nfree: Count } }
        /// Like `closure`, storing `env` in free slot 0.
        OpClosureEnv { args { dst: Register, constant: Constant, nfree: Count, env: Register } }
        OpFreeRef { args { dst: Register, index: Count } }
        OpClosureRef { args { dst: Register, closure: Register, index: Count } }
        OpClosureSet { args { closure: Register, index: Count, src: Register } }
        OpMakeEnv { args { dst: Register, size: Count } }
        OpEnvRef { args { dst: Register, env: Register, index: Count } }
        OpEnvSet { args { env: Register, index: Count, src: Register } }

        OpJump {
            args {
                #[relocatable(relative_start)]
                target: i32,
            }
        }
        OpJumpIfTrue {
            args {
                cond: Register,
                #[relocatable(relative_start)]
                target: i32,
            }
        }
        OpJumpIfFalse {
            args {
                cond: Register,
                #[relocatable(relative_start)]
                target: i32,
            }
        }
        OpJumpIfNull {
            args {
                src: Register,
                #[relocatable(relative_start)]
                target: i32,
            }
        }
        OpJumpIfNotNull {
            args {
                src: Register,
                #[relocatable(relative_start)]
                target: i32,
            }
        }
        OpJumpIfPair {
            args {
                src: Register,
                #[relocatable(relative_start)]
                target: i32,
            }
        }
        OpJumpIfNotPair {
            args {
                src: Register,
                #[relocatable(relative_start)]
                target: i32,
            }
        }
        OpJumpIfFixnum {
            args {
                src: Register,
                #[relocatable(relative_start)]
                target: i32,
            }
        }
        OpJumpIfNotFixnum {
            args {
                src: Register,
                #[relocatable(relative_start)]
                target: i32,
            }
        }
        OpJumpIfUndefined {
            args {
                src: Register,
                #[relocatable(relative_start)]
                target: i32,
            }
        }
        OpJumpIfNotUndefined {
            args {
                src: Register,
                #[relocatable(relative_start)]
                target: i32,
            }
        }
        OpJumpIfEq {
            args {
                lhs: Register,
                rhs: Register,
                #[relocatable(relative_start)]
                target: i32,
            }
        }
        OpJumpIfNotEq {
            args {
                lhs: Register,
                rhs: Register,
                #[relocatable(relative_start)]
                target: i32,
            }
        }
        OpJumpIfLess {
            args {
                lhs: Register,
                rhs: Register,
                #[relocatable(relative_start)]
                target: i32,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpJumpIfLessEqual {
            args {
                lhs: Register,
                rhs: Register,
                #[relocatable(relative_start)]
                target: i32,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpJumpIfNumberEqual {
            args {
                lhs: Register,
                rhs: Register,
                #[relocatable(relative_start)]
                target: i32,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpJumpIfGreaterEqual {
            args {
                lhs: Register,
                rhs: Register,
                #[relocatable(relative_start)]
                target: i32,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpJumpIfGreater {
            args {
                lhs: Register,
                rhs: Register,
                #[relocatable(relative_start)]
                target: i32,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpJumpIfNotLess {
            args {
                lhs: Register,
                rhs: Register,
                #[relocatable(relative_start)]
                target: i32,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpJumpIfNotLessEqual {
            args {
                lhs: Register,
                rhs: Register,
                #[relocatable(relative_start)]
                target: i32,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpJumpIfNotNumberEqual {
            args {
                lhs: Register,
                rhs: Register,
                #[relocatable(relative_start)]
                target: i32,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpJumpIfNotGreaterEqual {
            args {
                lhs: Register,
                rhs: Register,
                #[relocatable(relative_start)]
                target: i32,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpJumpIfNotGreater {
            args {
                lhs: Register,
                rhs: Register,
                #[relocatable(relative_start)]
                target: i32,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpSwitchFixnum { args { src: Register, table: PoolReference } }
        OpSwitchChar { args { src: Register, table: PoolReference } }
        OpSwitchSymbol { args { src: Register, table: PoolReference } }
        /// Loop header: poll the yield flag and increase hot counter.
        OpLoopHint { args { mask: PoolReference } }

        /// Non-tail call of `r[base+1]` with `argc` arguments in `r[base+2..]`.
        /// Always followed by a `return-point` or `return-point-forward` with `frame == base`.
        /// `r[base-1]` is reserved and raw across the call: it holds no live
        /// value and is in no return-point mask.
        OpCall {
            args {
                argc: Count,
                base: Register,
            }
            metadata {
                link: CallLinkInfo,
            }
        }
        /// Tail call of `r1` with `argc` arguments in `r2..`. The frame is
        /// reused, so unlike `call` there is no base and no reserved slot.
        OpTailCall {
            args {
                argc: Count,
            }
            metadata {
                link: CallLinkInfo,
            }
        }
        OpReturn { args { src: Register } }
        OpReturnValues { args { count: Count } }
        OpRaise { args { kind: Count, count: Count } }

        OpRestRef { args { dst: Register, cnt: Register, base: Register, index: Count } }
        OpRestLen { args { dst: Register, cnt: Register, skip: Count } }
        OpRestNull { args { dst: Register, cnt: Register, skip: Count } }
        OpRestPair { args { dst: Register, cnt: Register, skip: Count } }
        OpRestList { args { dst: Register, cnt: Register, base: Register, skip: Count } }
        OpValuesRest { args { base: Register, from: Count } }

        OpCallPrimitive0 { args { dst: Register, primitive: PrimitiveId } }
        OpCallPrimitive1 { args { dst: Register, primitive: PrimitiveId, a: Register } }
        OpCallPrimitive2 { args { dst: Register, primitive: PrimitiveId, a: Register, b: Register } }
        OpCallPrimitive3 { args { dst: Register, primitive: PrimitiveId, a: Register, b: Register, c: Register } }
        /// Arguments in `r[first .. first+argc]`.
        OpCallPrimitiveN { args { dst: Register, primitive: PrimitiveId, first: Register, argc: Count } }

        OpCar {
            args {
                dst: Register,
                src: Register,
            }
            metadata {
                profile: ValueProfile,
            }
        }
        OpCdr {
            args {
                dst: Register,
                src: Register,
            }
            metadata {
                profile: ValueProfile,
            }
        }
        OpCons { args { dst: Register, car: Register, cdr: Register } }
        OpSetCar { args { pair: Register, src: Register } }
        OpSetCdr { args { pair: Register, src: Register } }
        OpEq { args { dst: Register, lhs: Register, rhs: Register } }
        OpNot { args { dst: Register, src: Register } }
        OpAdd {
            args {
                dst: Register,
                lhs: Register,
                rhs: Register,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpSub {
            args {
                dst: Register,
                lhs: Register,
                rhs: Register,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpMul {
            args {
                dst: Register,
                lhs: Register,
                rhs: Register,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpAddImmediate {
            args {
                dst: Register,
                src: Register,
                value: Immediate,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpLess {
            args {
                dst: Register,
                lhs: Register,
                rhs: Register,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpLessEqual {
            args {
                dst: Register,
                lhs: Register,
                rhs: Register,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpNumberEqual {
            args {
                dst: Register,
                lhs: Register,
                rhs: Register,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpGreaterEqual {
            args {
                dst: Register,
                lhs: Register,
                rhs: Register,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpGreater {
            args {
                dst: Register,
                lhs: Register,
                rhs: Register,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpDiv {
            args {
                dst: Register,
                lhs: Register,
                rhs: Register,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpQuotient {
            args {
                dst: Register,
                lhs: Register,
                rhs: Register,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpRemainder {
            args {
                dst: Register,
                lhs: Register,
                rhs: Register,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpModulo {
            args {
                dst: Register,
                lhs: Register,
                rhs: Register,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpNegate {
            args {
                dst: Register,
                src: Register,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpAbs {
            args {
                dst: Register,
                src: Register,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpSqrt {
            args {
                dst: Register,
                src: Register,
            }
            metadata {
                profile: ArithProfile,
            }
        }
        OpVectorRef {
            args { dst: Register, vector: Register, index: Register }
            metadata { array: ArrayProfile, profile: ValueProfile }
        }
        OpVectorSet {
            args { vector: Register, index: Register, src: Register }
            metadata { array: ArrayProfile }
        }
        OpVectorLength { args { dst: Register, src: Register } }
        OpVariableRef {
            args {
                dst: Register,
                var: Register,
            }
            metadata {
                profile: ValueProfile,
            }
        }
        OpVariableSet { args { var: Register, src: Register } }

        /// `dst = (slot-ref obj 'name)`, jump to `slow` on a cache miss the
        /// runtime cannot fill.
        OpGetSlot {
            args {
                dst: Register,
                obj: Register,
                name: Constant,
                #[relocatable(relative_start)]
                slow: i32,
            }
            metadata { cache: SlotSite, profile: ValueProfile }
        }
        /// `(slot-set! obj 'name src)`, jump to `slow` on an unfillable miss.
        OpPutSlot {
            args {
                obj: Register,
                name: Constant,
                src: Register,
                #[relocatable(relative_start)]
                slow: i32,
            }
            metadata { cache: SlotSite }
        }

        // The bytecode compiler emits fused pairs (superinstructions) for
        // adjacent pairs. Every engine executes them as the sequence. New
        // opcodes append here so existing ids stay stable.
        // (`call` + `return-point` is deliberately not fused: the return point is
        // a resume target every return path addresses by bytecode pc, so a
        // fused op would need resume-offset dispatch in the return glue,
        // underflow, reinstatement, and the JIT resume table.)

        /// Two moves in order: `r[dst1] = r[src1]`, then `r[dst2] = r[src2]`.
        OpMoveTwo {
            args { dst1: Register, src1: Register, dst2: Register, src2: Register }
        }
        /// `tmp = src + value`, then `dst = tmp`.
        OpAddImmediateMove {
            args { tmp: Register, src: Register, value: Immediate, dst: Register }
            metadata { profile: ArithProfile }
        }
        /// `vdst = vector[vector][index]`, then `mdst = lhs * rhs`: a
        OpVectorRefMul {
            args { vdst: Register, vector: Register, index: Register, mdst: Register, lhs: Register, rhs: Register }
            metadata { array: ArrayProfile, profile: ValueProfile, arith: ArithProfile }
        }

        OpCallSelf {
            args { argc: Count, base: Register }
            metadata { link: CallLinkInfo }
        }
        OpTailCallSelf {
            args {
                argc: Count,
            }
            metadata {
                link: CallLinkInfo,
            }
        }
    }
}

/// Header size of a capy instruction at width `W`.
#[inline(always)]
pub const fn header_size<const W: u8>() -> usize {
    match W {
        0 => 1,
        1 => 3,
        _ => 5,
    }
}

/// Decode the width and opcode of the instruction at `ip`, return the
/// pointer to its first operand.
///
/// # Safety
/// `ip` points at the first byte of a valid instruction.
#[inline(always)]
pub unsafe fn decode_header(ip: *const u8) -> (bytecodegen::OperandWidth, OpcodeId, *const u8) {
    use bytecodegen::{WIDE16_PREFIX, WIDE32_PREFIX};
    unsafe {
        let first = *ip;
        let (width, opcode) = match first {
            WIDE16_PREFIX => (
                bytecodegen::OperandWidth::Wide16,
                ip.add(1).cast::<u16>().read_unaligned() as u8,
            ),
            WIDE32_PREFIX => (
                bytecodegen::OperandWidth::Wide32,
                ip.add(1).cast::<u32>().read_unaligned() as u8,
            ),
            byte => (bytecodegen::OperandWidth::Narrow, byte),
        };
        let header = match width {
            bytecodegen::OperandWidth::Narrow => 1,
            bytecodegen::OperandWidth::Wide16 => 3,
            bytecodegen::OperandWidth::Wide32 => 5,
        };

        let opcode = OpcodeId::from_u8(opcode).unwrap_unchecked();
        (width, opcode, ip.add(header))
    }
}

pub const MV_ERROR: u32 = 0;
pub const MV_IGNORE: u32 = 1;

pub const SWITCH_DENSE_FLAG: u32 = 0x8000_0000;

pub fn switch_table_is_dense(count: u32) -> bool {
    count & SWITCH_DENSE_FLAG != 0
}

pub fn switch_table_len(count: u32) -> usize {
    (count & !SWITCH_DENSE_FLAG) as usize
}

/// Hash of the instruction set and the primitive table, stored in every
/// FASL file.
pub fn format_hash() -> u64 {
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    let mut feed = |bytes: &[u8]| {
        for byte in bytes {
            hash ^= *byte as u64;
            hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
        }
        hash ^= 0xff;
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    };
    feed(BYTECODE_SIGNATURE.as_bytes());
    for prim in crate::runtime::prims::def::Primitive::ALL {
        feed(prim.name().as_bytes());
    }
    hash
}

/// An opcode with a metadata array: the type-level index engines use to
/// read that array through a
/// [`MetadataArea`](crate::runtime::interp::rust_interp::MetadataArea).
pub(crate) trait OpcodeWithMetadata {
    /// This opcode's metadata entry type (`OpCarMetadata`, ...).
    type Metadata;

    /// Entry `id` of this opcode's metadata array in `base`.
    ///
    /// # Safety
    ///
    /// `base` is an initialized flat metadata area with more than `id`
    /// entries of this opcode's kind.
    unsafe fn metadata_entry(base: *mut u8, id: MetadataId) -> *mut Self::Metadata;
}

macro_rules! impl_opcode_with_metadata {
    ($(($Op:ident, $Meta:ident, $kind:expr, { $($field:ident : $ty:ty),* }),)*) => {
        $(
            impl OpcodeWithMetadata for $Op {
                type Metadata = $Meta;

                #[inline(always)]
                unsafe fn metadata_entry(base: *mut u8, id: MetadataId) -> *mut Self::Metadata {
                    unsafe { Self::metadata_ptr(base, id) }
                }
            }
        )*
    };
}

for_each_metadata!(impl_opcode_with_metadata);

pub fn encode_all(instructions: &[Instruction]) -> Vec<u8> {
    use bytecodegen::{Emit, Encode};
    let mut out = Vec::new();
    for insn in instructions {
        // `u32`/`i32` operands always fit wide32, so this never fails.
        let width = insn.smallest_width().expect("fixture fits wide32");
        let size = insn.encoded_len(width);
        let start = out.len();
        out.resize(start + size, 0);
        let mut sink = bytecodegen::SliceSink::new(&mut out[start..]);
        insn.encode_with_width(&mut sink, width);
        debug_assert_eq!(sink.position(), size);
    }
    out
}
